import json
import re
import pandas as pd

def task_func(json_str):
    """
    Load a JSON string into a dictionary, double all numeric values
    (including those represented as strings), and create a Pandas
    DataFrame from the resulting data. If the input is empty or
    invalid, an empty DataFrame is returned. All numeric columns
    are converted to float type where possible, leaving non-numeric
    types unchanged.

    Parameters
    ----------
    json_str : str
        A JSON-formatted string representing either a dictionary
        or a list of dictionaries (records).

    Returns
    -------
    pd.DataFrame
        DataFrame constructed from the parsed and normalized JSON data.
    """
    # Helper to recursively double numeric values
    def _double_numbers(obj):
        if isinstance(obj, dict):
            return {k: _double_numbers(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_double_numbers(v) for v in obj]
        if isinstance(obj, (int, float)):
            return obj * 2
        if isinstance(obj, str):
            # Try integer conversion
            try:
                val = int(obj)
                return val * 2
            except ValueError:
                pass
            # Try float conversion
            try:
                val = float(obj)
                return val * 2
            except ValueError:
                pass
        return obj

    # Return empty DataFrame for empty or whitespace-only input
    if not json_str or json_str.strip() == "":
        return pd.DataFrame()

    # Attempt to parse the JSON string
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        # Fallback: replace single quotes with double quotes (naive approach)
        cleaned = re.sub(r"(?<!\\)'", r'"', json_str)
        try:
            data = json.loads(cleaned)
        except json.JSONDecodeError:
            return pd.DataFrame()

    # Validate parsed data
    if data is None:
        return pd.DataFrame()
    if isinstance(data, (dict, list)) and not data:
        return pd.DataFrame()
    if not isinstance(data, (dict, list)):
        return pd.DataFrame()

    # Normalize numeric values
    normalized_data = _double_numbers(data)

    # Create DataFrame
    df = pd.DataFrame(normalized_data)

    # Convert numeric columns to float where possible, excluding bool
    numeric_cols = (
        df.select_dtypes(include=["number"])
        .columns.difference(df.select_dtypes(include=["bool"]).columns)
    )
    if not numeric_cols.empty:
        df[numeric_cols] = df[numeric_cols].astype(float)

    return df

