import subprocess
import psutil

def task_func(process_name: str) -> str:
    """
    Check if a process with the given name is running.
    If it is, return '<process_name> is running'.
    If not, start it using the process name as a command and
    return 'Process not found. Starting <process_name>.'.
    """
    # Search for the process by name
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                return f'{process_name} is running'
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue

    # Process not found – attempt to start it
    try:
        subprocess.Popen([process_name])
    except Exception:
        # If starting fails, we still return the same message
        pass

    return f'Process not found. Starting {process_name}.'

from flask import Flask, render_template, redirect, url_for, request
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.secret_key = 'replace_with_a_secure_random_key'  # Needed for session and CSRF protection

# ---------- Flask-Login setup ----------
login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'  # Redirect to login page if not authenticated

# ---------- User model ----------
class User(UserMixin):
    def __init__(self, id_, username, password_hash):
        self.id = id_
        self.username = username
        self.password_hash = password_hash

# In‑memory user store (id -> User)
users = {}
# Create a demo user: username 'demo', password 'secret'
demo_user = User(id_=1, username='demo', password_hash=generate_password_hash('secret'))
users[demo_user.id] = demo_user

# User loader callback for Flask-Login
@login_manager.user_loader
def load_user(user_id):
    return users.get(int(user_id))

# ---------- WTForms ----------
class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired()])
    password = PasswordField('Password', validators=[DataRequired()])
    submit = SubmitField('Login')

# ---------- Routes ----------
@app.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        # Find user by username
        user = next((u for u in users.values() if u.username == form.username.data), None)
        if user and check_password_hash(user.password_hash, form.password.data):
            login_user(user)
            return redirect(url_for('welcome'))
        else:
            return 'Invalid credentials', 401
    return '''
        <!doctype html>
        <title>Login</title>
        <h1>Login</h1>
        <form method="post">
            {}<br>
            <p>Username: <input type="text" name="username"></p>
            <p>Password: <input type="password" name="password"></p>
            <p><input type="submit" value="Login"></p>
        </form>
    '''.format(form.csrf_token)

@app.route('/welcome')
@login_required
def welcome():
    return f'Hello, {current_user.username}!'

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('login'))

# ---------- Run ----------
if __name__ == '__main__':
    app.run(debug=True)

